import type{Metadata}from"next";
import Navigation from"../Navigation";
import SiteFooter from"../SiteFooter";
import MotionSystem from"../MotionSystem";
import ArrowUpRightIcon from"../ArrowUpRightIcon";
import{oregonImages}from"../site-content";

export const metadata:Metadata={title:"About Our Portland Technology Company",description:"Meet the owner-led Portland technology company providing IT support, web design, local SEO, networking, and technology services with direct, personal service.",alternates:{canonical:"/about"},openGraph:{title:"About Torres & Co. Technology",description:"Owner-led technology, website, local search, and systems work for Oregon businesses and homes.",url:"/about",type:"website",images:[{url:oregonImages[0].src,alt:oregonImages[0].alt}]}};

const disciplines=[
  ["Web experiences","Multi-page business websites, luxury property presentations, responsive interfaces, forms, booking and ordering paths."],
  ["Search foundations","Service architecture, local content, metadata, schema, sitemaps, Search Console, analytics, and conversion measurement."],
  ["Business technology","Devices, accounts, software, vendor coordination, backups, technology planning, and ongoing owner-led support."],
  ["Networks & property systems","Wi-Fi, Ethernet, mesh networks, Starlink integration, camera planning, remote viewing, and residential technology."]
];

export default function AboutPage(){return <main className="innerPage aboutDetailPage"><MotionSystem/><Navigation/>
  <header className="aboutHero shell"><div><p className="eyebrow"><span/> Owner-led · Portland, Oregon</p><h1>Modern technology, delivered with old-fashioned service.</h1><p>Torres &amp; Co. Technology is a locally operated technology company serving Portland-area small businesses and homes. Clients work directly with the owner from the first conversation through delivery and ongoing support.</p></div><figure><img src={oregonImages[0].src} alt={oregonImages[0].alt}/><figcaption><span>Built in Portland. Available across the metro and beyond when the project calls for it.</span><a href={oregonImages[0].source} target="_blank" rel="noopener noreferrer">Photo: {oregonImages[0].credit} · {oregonImages[0].license}</a></figcaption></figure></header>
  <section className="pageBand"><div className="shell aboutPageGrid"><img src="/images/residential-technology-portland.jpg" alt="Owner of Torres & Co. Technology in downtown Portland"/><div><p className="sectionLabel">The working relationship</p><h2>Personal service is part of the technology.</h2><p>Good technology work is not only about equipment or code. It is also about listening carefully, communicating clearly, taking responsibility, and leaving a client with systems they understand.</p><div className="valueGrid"><div><strong>Direct communication</strong><p>Clear answers in plain language.</p></div><div><strong>Accountability</strong><p>One person responsible for the work.</p></div><div><strong>Careful workmanship</strong><p>Thoughtful setups built around the need.</p></div><div><strong>Honest recommendations</strong><p>Guidance shaped around practical goals.</p></div></div></div></div></section>
  <section className="disciplineSection shell"><div className="disciplineIntro"><p className="sectionLabel">What the work covers</p><h2>A connected view of technology and customer experience.</h2><p>The value is not a long list of disconnected services. It is the ability to understand how the website, search presence, customer actions, internal systems, and physical network affect one another.</p></div><div className="disciplineGrid">{disciplines.map(([title,body],index)=><article key={title}><span>0{index+1}</span><h3>{title}</h3><p>{body}</p></article>)}</div></section>
  <section className="verifiedPractice"><div className="shell"><div><p className="sectionLabel">Work in practice</p><h2>Different industries. The same attention to clarity.</h2></div><div className="practiceList"><a href="/work/hvac-ministries"><span>Salem, Oregon</span><strong>HVAC Ministries</strong><p>Multi-page service website, booking and review paths, local content, and analytics.</p><ArrowUpRightIcon/></a><a href="/work/taqueria-portland"><span>Portland, Oregon</span><strong>Taqueria Portland</strong><p>Two-location restaurant website, menu and story content, directions, and ordering paths.</p><ArrowUpRightIcon/></a><a href="/work/the-columbia-estate"><span>Vancouver, Washington</span><strong>The Columbia Estate</strong><p>Luxury property storytelling, relocation content, structured data, and a private-tour experience.</p><ArrowUpRightIcon/></a></div></div></section>
  <section className="shell splitStatement"><p className="sectionLabel">Start with the real need</p><div><h2>No generic package is more important than the actual problem.</h2><p>Every engagement begins with the business, home, property, people, and desired outcome. The recommended scope is written around what can be responsibly delivered. Local SEO and marketing build over time; no specific ranking, lead volume, or sale is guaranteed.</p><a className="textLink" href="/contact">Start a conversation <ArrowUpRightIcon/></a></div></section><SiteFooter/>
</main>}

